function t(k, vars){
  let s = (I18N[DB.settings.lang] && I18N[DB.settings.lang][k]) || I18N.en[k] || k;
  if(vars) for(const n in vars) s = s.split('{'+n+'}').join(String(vars[n]));
  return s;
}

function tCat(c){ return t('category.' + c, {}) || c; }

function tPay(m){ const map = {Cash:'payment.cash','Bank Transfer':'payment.bank','QR Payment':'payment.qr',Card:'payment.card',Other:'payment.other'}; return t(map[m] || 'payment.other'); }

function tExpCat(c){ return t('expenseCategory.' + c) || c; }

function tStatus(s){ return s === 'Completed' ? t('orders.completed') : s === 'Refunded' ? t('orders.refunded') : t('orders.cancelled'); }

function tRole(r){
  const k = String(r || '').toLowerCase();
  if(k === 'owner') return t('staff.owner');
  if(k === 'admin') return t('staff.admin');
  if(k === 'manager') return t('staff.manager');
  return t('staff.cashier');
}

