const KEY = 'posHtml.v1';

const CUR = { THB:{sym:'฿',dec:2}, MMK:{sym:'Ks',dec:0}, USD:{sym:'$',dec:2}, SGD:{sym:'S$',dec:2} };

const CATEGORIES = ['Phones','Accessories','Chargers','Cables','Earphones','Power Banks','Cases','Screen Protectors'];

const EXP_CATS = ['Rent','Electricity','Water','Salary','Transportation','Supplies','Marketing','Other'];

const PAY_METHODS = ['Cash','Bank Transfer','QR Payment','Card','Other'];

const PROD_ICON = { Phones:'📱', Chargers:'🔌', Earphones:'🎧', 'Power Banks':'🔋', Cables:'🔌', Cases:'📱', 'Screen Protectors':'🛡️', Accessories:'🧩' };
/* Product photo if one is saved, else the category icon. A photo lives in
   Supabase Storage as a file; the product record holds its public URL
   (p.photo). While an upload is pending, the compressed JPEG data URI sits
   in p.photoPending (local only, never sent to the cloud) and is shown
   instead — it is the newest photo the user picked. */

function prodTile(p){
  const src = (p && (p.photoPending || p.photo)) || '';
  if(src) return '<img src="' + esc(src) + '" alt="">';
  return PROD_ICON[(p && p.category) || ''] || '📦';
}
/* Shrink a picked photo to max 400px on the longest side as JPEG ~0.75, so
   one photo stays ~30-60KB. Returns {uri, blob}: the data URI is the local
   preview / pending representation, the Blob is what gets uploaded to
   Supabase Storage. White behind it: JPEG has no transparency (a PNG logo
   would otherwise get a black background). */

let curView = 'dashboard';

function uid(p){ return p + Date.now().toString(36) + Math.floor(Math.random()*1296).toString(36); }

function esc(s){ return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }

function round2(n){ return Math.round((n + Number.EPSILON) * 100) / 100; }

function money(n){
  const c = CUR[DB.settings.currency] || CUR.THB;
  return c.sym + Number(n || 0).toLocaleString('en-US', {minimumFractionDigits: c.dec, maximumFractionDigits: c.dec});
}

function moneyPlain(n){
  const c = CUR[DB.settings.currency] || CUR.THB;
  return Number(n || 0).toLocaleString('en-US', {minimumFractionDigits: c.dec, maximumFractionDigits: c.dec});
}

function effPrice(p){ return (p.discountPrice != null && p.discountPrice > 0 && p.discountPrice < p.sellingPrice) ? p.discountPrice : p.sellingPrice; }

function prodById(id){ return DB.products.find(function(p){ return p.id === id; }); }

function custById(id){ return DB.customers.find(function(c){ return c.id === id; }); }

function fmtDate(ts){
  const d = new Date(ts);
  const pad = function(n){ return String(n).padStart(2,'0'); };
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}

function fmtDay(ts){
  const d = new Date(ts);
  const pad = function(n){ return String(n).padStart(2,'0'); };
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
}

function isToday(ts){ const a = new Date(ts), b = new Date(); return a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate(); }

function isThisMonth(ts){ const a = new Date(ts), b = new Date(); return a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth(); }

function atDay(offset, h, m){
  const d = new Date(); d.setDate(d.getDate() - offset); d.setHours(h, m, 0, 0); return d.getTime();
}

