function toast(msg){
  const el = document.getElementById('toast');
  el.textContent = msg; el.classList.remove('hidden');
  clearTimeout(toast._t);
  toast._t = setTimeout(function(){ el.classList.add('hidden'); }, 2600);
}

/* ================= cash drawer (WebUSB + ESC/POS) ================= */
/* The drawer is driven by the receipt printer: the printer sends a pulse to
   the drawer port. The kick command is ESC/POS: ESC p m t1 t2
   (1B 70 00 19 FA = drawer 1, 25ms on / 250ms off). Best-effort only: a
   failed kick never blocks a sale. Hardware prefs live in their own
   localStorage key (per device) so cloud sync never touches them. */

