  document.getElementById('mobileCartFab').addEventListener('click', function(){
    // open the cart as a modal on mobile
    const panel = document.getElementById('cartPanel');
    openModal('<header class="cart-sheet-head"><button class="btn icon-btn" type="button" data-close aria-label="Back">' + BACK_SVG + '</button><h2>' + esc(t('cart.title')) + '</h2><button class="btn icon-btn" type="button" id="cartSheetTrash" aria-label="' + esc(t('cart.clear')) + '">' + TRASH_SVG + '</button></header><div id="mobileCartBody"></div>');
    const body = document.getElementById('mobileCartBody');
    body.appendChild(panel);
    panel.style.display = 'flex';
    panel.style.position = 'static';
    panel.style.height = 'auto';
    panel.style.maxHeight = '70vh';
    panel.style.padding = '0';
    panel.style.border = '0';
    const closeBtn = document.querySelector('#modalBox [data-close]');
    const restore = function(){
      panel.style.display = ''; panel.style.position = ''; panel.style.height = '';
      panel.style.maxHeight = ''; panel.style.padding = ''; panel.style.border = '';
      document.getElementById('view-pos').appendChild(panel);
    };
    if(closeBtn) closeBtn.addEventListener('click', restore);
    const sheetTrash = document.getElementById('cartSheetTrash');
    if(sheetTrash) sheetTrash.addEventListener('click', function(){ cart = []; renderCart(); });
    document.getElementById('modalBackdrop').addEventListener('click', restore, { once: true });
  });
  document.getElementById('productSearch').addEventListener('input', function(){ prodPage = 1; renderProducts(); });
  document.getElementById('productFilter').addEventListener('change', function(){ prodPage = 1; renderProducts(); });
  document.getElementById('productSort').addEventListener('change', function(){ prodPage = 1; renderProducts(); });
